    LeadAssignmentBatch = apps.get_model('leads', 'LeadAssignmentBatch')

    assignments = list(
        LeadAssignment.objects.filter(batch__isnull=True)
        .select_related('lead', 'assigned_to', 'assigned_by')
        .order_by('timestamp', 'id')
    )
    if not assignments:
        return

    current_group = None
    grouped = []

    for row in assignments:
        comp = row.lead.company if row.lead_id else 'LP'
        key = (row.assigned_to_id, row.assigned_by_id, row.assignment_type, comp)
        if (
            current_group
            and current_group['key'] == key
            and (row.timestamp - current_group['last_ts']) <= timedelta(minutes=2)
        ):
            current_group['rows'].append(row)
            current_group['last_ts'] = row.timestamp
        else:
            current_group = {
                'key': key,
                'first_ts': row.timestamp,
                'last_ts': row.timestamp,
                'rows': [row],
            }
            grouped.append(current_group)

    latest_batch_by_lead = {}

    for grp in grouped:
        rows = grp['rows']
        first = rows[0]
        comp = first.lead.company if first.lead_id else 'LP'
        count = len(rows)
        local_ts = timezone.localtime(grp['first_ts']).strftime('%d %b %Y, %I:%M %p')
        actor = ''
        if first.assigned_by_id and first.assigned_by:
            actor = (f"{first.assigned_by.first_name} {first.assigned_by.last_name}".strip() or first.assigned_by.username)
        title = f"{count} lead{'s' if count != 1 else ''} assigned"
        if actor:
            title += f" by {actor}"
        title += f" · {local_ts}"

        batch = LeadAssignmentBatch.objects.create(
            company=comp or 'LP',
            title=title[:255],
            assigned_to_id=first.assigned_to_id,
            assigned_by_id=first.assigned_by_id,
            assignment_type=first.assignment_type or 'PRIMARY',
            notes=(first.notes or '')[:1000],
            total_leads_count=count,
        )
        LeadAssignmentBatch.objects.filter(pk=batch.pk).update(created_at=grp['first_ts'])

        row_ids = [r.id for r in rows]
        LeadAssignment.objects.filter(id__in=row_ids).update(batch_id=batch.id)

        for r in rows:
            latest_batch_by_lead[r.lead_id] = (batch.id, r.assigned_to_id, r.assignment_type)

    # Set current_assignment_batch on leads whose current assignee matches their latest assignment
    lead_ids = list(latest_batch_by_lead.keys())
    leads_to_update = []
    for lead in Lead.objects.filter(id__in=lead_ids):
        batch_id, assigned_to_id, assignment_type = latest_batch_by_lead[lead.id]
        current_owner_id = lead.sub_assigned_to_id if assignment_type == 'SUB' else lead.assigned_to_id
        if current_owner_id == assigned_to_id:
            lead.current_assignment_batch_id = batch_id
            leads_to_update.append(lead)
    if leads_to_update:
        Lead.objects.bulk_update(leads_to_update, ['current_assignment_batch'], batch_size=1000)


